-- PRD-001 additive catalog schema. Preserve all existing IDs and OSS objects.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS kb_source_profile (
 source_id BIGINT NOT NULL PRIMARY KEY, description TEXT, subject VARCHAR(40), resource_type VARCHAR(40) NOT NULL DEFAULT 'UNKNOWN', origin_kind VARCHAR(40) DEFAULT 'UNKNOWN', published_year SMALLINT, prepared_year SMALLINT, author_name VARCHAR(200), publisher_name VARCHAR(200), acquired_at DATETIME, catalog_status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', audience_role VARCHAR(30), provenance_status VARCHAR(30) DEFAULT 'UNKNOWN', row_version BIGINT NOT NULL DEFAULT 0, create_by VARCHAR(64) NOT NULL DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_by VARCHAR(64) NOT NULL DEFAULT '', update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_source_profile_class(subject,resource_type,catalog_status), KEY idx_source_published(published_year), KEY idx_source_prepared(prepared_year),
 CONSTRAINT fk_source_profile_root FOREIGN KEY(source_id) REFERENCES kb_source(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_source_outline_scope (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, source_id BIGINT NOT NULL, outline_id BIGINT NOT NULL, scope_kind VARCHAR(30) NOT NULL, note VARCHAR(2000), row_version BIGINT NOT NULL DEFAULT 0, create_by VARCHAR(64) NOT NULL DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_by VARCHAR(64) NOT NULL DEFAULT '', update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_source_outline(source_id,outline_id), KEY idx_source_scope_outline(outline_id,source_id),
 CONSTRAINT fk_source_scope_root FOREIGN KEY(source_id) REFERENCES kb_source(id), CONSTRAINT fk_source_scope_outline FOREIGN KEY(outline_id) REFERENCES kb_outline(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_source_outline_scope_node (
 scope_id BIGINT NOT NULL,node_id BIGINT NOT NULL,PRIMARY KEY(scope_id,node_id), KEY idx_source_scope_node(node_id,scope_id),
 CONSTRAINT fk_source_scope_node_parent FOREIGN KEY(scope_id) REFERENCES kb_source_outline_scope(id), CONSTRAINT fk_source_scope_node_id FOREIGN KEY(node_id) REFERENCES kb_outline_node(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_source_kp (
 source_id BIGINT NOT NULL,kp_id BIGINT NOT NULL,PRIMARY KEY(source_id,kp_id), KEY idx_source_kp_reverse(kp_id,source_id),
 CONSTRAINT fk_source_kp_root FOREIGN KEY(source_id) REFERENCES kb_source(id), CONSTRAINT fk_source_kp_point FOREIGN KEY(kp_id) REFERENCES kb_kp(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_product_profile (
 product_id BIGINT NOT NULL PRIMARY KEY, description TEXT, subject VARCHAR(40), resource_type VARCHAR(40) NOT NULL DEFAULT 'UNKNOWN', origin_kind VARCHAR(40) DEFAULT 'UNKNOWN', published_year SMALLINT, prepared_year SMALLINT, author_name VARCHAR(200), publisher_name VARCHAR(200), acquired_at DATETIME, catalog_status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', audience_role VARCHAR(30), provenance_status VARCHAR(30) DEFAULT 'UNKNOWN', row_version BIGINT NOT NULL DEFAULT 0, create_by VARCHAR(64) NOT NULL DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_by VARCHAR(64) NOT NULL DEFAULT '', update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_product_profile_class(subject,resource_type,catalog_status), KEY idx_product_published(published_year), KEY idx_product_prepared(prepared_year),
 CONSTRAINT fk_product_profile_root FOREIGN KEY(product_id) REFERENCES kb_product(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_product_outline_scope (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, product_id BIGINT NOT NULL, outline_id BIGINT NOT NULL, scope_kind VARCHAR(30) NOT NULL, note VARCHAR(2000), row_version BIGINT NOT NULL DEFAULT 0, create_by VARCHAR(64) NOT NULL DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_by VARCHAR(64) NOT NULL DEFAULT '', update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_product_outline(product_id,outline_id), KEY idx_product_scope_outline(outline_id,product_id),
 CONSTRAINT fk_product_scope_root FOREIGN KEY(product_id) REFERENCES kb_product(id), CONSTRAINT fk_product_scope_outline FOREIGN KEY(outline_id) REFERENCES kb_outline(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_product_outline_scope_node (
 scope_id BIGINT NOT NULL,node_id BIGINT NOT NULL,PRIMARY KEY(scope_id,node_id), KEY idx_product_scope_node(node_id,scope_id),
 CONSTRAINT fk_product_scope_node_parent FOREIGN KEY(scope_id) REFERENCES kb_product_outline_scope(id), CONSTRAINT fk_product_scope_node_id FOREIGN KEY(node_id) REFERENCES kb_outline_node(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_product_kp (
 product_id BIGINT NOT NULL,kp_id BIGINT NOT NULL,PRIMARY KEY(product_id,kp_id), KEY idx_product_kp_reverse(kp_id,product_id),
 CONSTRAINT fk_product_kp_root FOREIGN KEY(product_id) REFERENCES kb_product(id), CONSTRAINT fk_product_kp_point FOREIGN KEY(kp_id) REFERENCES kb_kp(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_region (
 region_code VARCHAR(32) NOT NULL PRIMARY KEY,parent_code VARCHAR(32),name VARCHAR(100) NOT NULL,level INT NOT NULL,status CHAR(1) NOT NULL DEFAULT '0',standard_code VARCHAR(32),source_url VARCHAR(1000),valid_from DATE,valid_until DATE,row_version BIGINT NOT NULL DEFAULT 0, create_by VARCHAR(64) NOT NULL DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_by VARCHAR(64) NOT NULL DEFAULT '', update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_region_parent(parent_code,status),CONSTRAINT fk_region_parent FOREIGN KEY(parent_code) REFERENCES kb_region(region_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_source_region (
 source_id BIGINT NOT NULL,region_role VARCHAR(30) NOT NULL,region_code VARCHAR(32) NOT NULL,PRIMARY KEY(source_id,region_role,region_code),KEY idx_source_region_lookup(region_code,region_role,source_id),CONSTRAINT fk_source_region_root FOREIGN KEY(source_id) REFERENCES kb_source(id),CONSTRAINT fk_source_region_code FOREIGN KEY(region_code) REFERENCES kb_region(region_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_product_region (
 product_id BIGINT NOT NULL,region_role VARCHAR(30) NOT NULL,region_code VARCHAR(32) NOT NULL,PRIMARY KEY(product_id,region_role,region_code),KEY idx_product_region_lookup(region_code,region_role,product_id),CONSTRAINT fk_product_region_root FOREIGN KEY(product_id) REFERENCES kb_product(id),CONSTRAINT fk_product_region_code FOREIGN KEY(region_code) REFERENCES kb_region(region_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_exam_source_detail (
 source_id BIGINT NOT NULL PRIMARY KEY,entrance_stage VARCHAR(40),organizer_level VARCHAR(40),paper_nature VARCHAR(40) NOT NULL DEFAULT 'UNKNOWN',exam_date DATE,academic_year_start SMALLINT,term VARCHAR(20),session_label VARCHAR(100),paper_code VARCHAR(100),organizer_name VARCHAR(200),evidence_asset_id BIGINT,verified_at DATETIME,verified_by VARCHAR(64),identity_fingerprint CHAR(64),row_version BIGINT NOT NULL DEFAULT 0, create_by VARCHAR(64) NOT NULL DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_by VARCHAR(64) NOT NULL DEFAULT '', update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_exam_dimensions(paper_nature,organizer_level),
 CONSTRAINT fk_exam_detail_root FOREIGN KEY(source_id) REFERENCES kb_exam_source(source_id),CONSTRAINT fk_exam_detail_evidence FOREIGN KEY(evidence_asset_id) REFERENCES kb_asset(asset_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_occurrence_collection (
 occurrence_id BIGINT NOT NULL,collection_kind VARCHAR(40) NOT NULL,note VARCHAR(2000),evidence_asset_id BIGINT,row_version BIGINT NOT NULL DEFAULT 0, create_by VARCHAR(64) NOT NULL DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_by VARCHAR(64) NOT NULL DEFAULT '', update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(occurrence_id,collection_kind),KEY idx_collection_kind(collection_kind,occurrence_id),CONSTRAINT fk_collection_occurrence FOREIGN KEY(occurrence_id) REFERENCES kb_question_source(id),CONSTRAINT fk_collection_evidence FOREIGN KEY(evidence_asset_id) REFERENCES kb_asset(asset_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_product_question (
 product_id BIGINT NOT NULL,seq INT NOT NULL,question_id BIGINT NOT NULL,question_row_version BIGINT NOT NULL,stem_hash CHAR(64) NOT NULL,item_locator VARCHAR(500),PRIMARY KEY(product_id,seq),KEY idx_product_question(question_id,product_id),CONSTRAINT fk_product_question_root FOREIGN KEY(product_id) REFERENCES kb_product(id),CONSTRAINT fk_product_question_question FOREIGN KEY(question_id) REFERENCES kb_question(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS kb_product_reference_source (
 product_id BIGINT NOT NULL,source_id BIGINT NOT NULL,note VARCHAR(2000),PRIMARY KEY(product_id,source_id),KEY idx_product_source(source_id,product_id),CONSTRAINT fk_product_source_root FOREIGN KEY(product_id) REFERENCES kb_product(id),CONSTRAINT fk_product_source_source FOREIGN KEY(source_id) REFERENCES kb_source(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- Conservative legacy mapping: never infer textbook, year, region or administered exam evidence.
 SELECT s.id,e.subject,CASE s.source_kind WHEN 'EXAM' THEN 'EXAM_PAPER' WHEN 'HANDOUT' THEN 'HANDOUT' WHEN 'WORKBOOK' THEN 'WORKBOOK' ELSE 'UNKNOWN' END,CASE s.source_kind WHEN 'AUTHORED' THEN 'AUTHORED' ELSE 'UNKNOWN' END,'DRAFT','migration' FROM kb_source s LEFT JOIN kb_exam_source e ON e.source_id=s.id;

-- Shared effective source identity used by every true-exam read path.
CREATE OR REPLACE VIEW kb_verified_exam_source AS
 SELECT e.* FROM kb_exam_source e JOIN kb_source s ON s.id=e.source_id
 JOIN kb_source_profile p ON p.source_id=e.source_id AND p.subject=e.subject
 JOIN kb_exam_source_detail d ON d.source_id=e.source_id
 JOIN kb_asset a ON a.asset_id=d.evidence_asset_id AND a.status='READY'
 WHERE s.source_kind='EXAM' AND e.authenticity_status='VERIFIED'
 AND d.paper_nature='ACTUAL_ADMINISTERED' AND d.identity_fingerprint IS NOT NULL
 AND d.verified_at IS NOT NULL AND d.verified_by IS NOT NULL
 AND EXISTS(SELECT 1 FROM kb_source_asset sa WHERE sa.source_id=e.source_id AND sa.asset_id=d.evidence_asset_id);
